    "clinicalPearl": "【中榮 ML-SIP-020 印度墨染色 SOP】用於腦脊髓液 (CSF) 快速篩檢新型隱球菌 (*Cryptococcus neoformans*)。印度墨為負染色法，墨汁顆粒無法穿透厚多醣莢膜，在暗黑視野中呈現圓形透明透亮光暈 (Halo)。",
    "mentorPrompt": "二年期學員可問實習生：「CSF 印度墨鏡檢時，如何區分新型隱球菌與白血球淋巴球或紅血球？如何確認出芽特徵 (narrow-based budding)？」",
